205|int spng_set_crc_action(spng_ctx *ctx, int critical, int ancillary)
206|{
207|    if(ctx == NULL) return 1;
208|
209|    if(critical > 2 || critical < 0) return 1;
210|    if(ancillary > 2 || critical < 0) return 1;
211|
212|    if(critical == SPNG_CRC_DISCARD) return 1;
213|
214|    ctx->crc_action_critical = critical;
215|    ctx->crc_action_ancillary = ancillary;
216|
217|    return 0;
