22|static inline uint32_t read_u32(const void *_data)
23|{
24|    const unsigned char *data = _data;
25|
26|    return (data[0] & 0xffUL) << 24 | (data[1] & 0xffUL) << 16 |
27|           (data[2] & 0xffUL) << 8  | (data[3] & 0xffUL);
28|}
