30|static inline int32_t read_s32(const void *_data)
31|{
32|    const unsigned char *data = _data;
33|
34|    int32_t ret;
35|    uint32_t val = (data[0] & 0xffUL) << 24 | (data[1] & 0xffUL) << 16 |
36|                   (data[2] & 0xffUL) << 8  | (data[3] & 0xffUL);
37|
38|    memcpy(&ret, &val, 4);
39|
40|    return ret;
