51|static inline int read_data(spng_ctx *ctx, size_t bytes)
52|{
53|    if(ctx == NULL) return 1;
54|    if(!bytes) return 0;
55|
56|    if(ctx->streaming && (bytes > ctx->data_size))
57|    {
58|        void *buf = spng__realloc(ctx, ctx->data, bytes);
59|        if(buf == NULL) return SPNG_EMEM;
60|
61|        ctx->data = buf;
62|        ctx->data_size = bytes;
63|    }
64|
65|    int ret;
66|    ret = ctx->read_fn(ctx, ctx->read_user_ptr, ctx->data, bytes);
67|    if(ret) return ret;
68|
69|    ctx->bytes_read += bytes;
70|    if(ctx->bytes_read < bytes) return SPNG_EOVERFLOW;
71|
72|    return 0;
73|}
