75|static inline int read_and_check_crc(spng_ctx *ctx)
76|{
77|    if(ctx == NULL) return 1;
78|
79|    int ret;
80|    ret = read_data(ctx, 4);
81|    if(ret) return ret;
82|
83|    ctx->current_chunk.crc = read_u32(ctx->data);
84|
85|    if(is_critical_chunk(&ctx->current_chunk) && ctx->crc_action_critical == SPNG_CRC_USE)
86|        goto skip_crc;
87|    else if(ctx->crc_action_ancillary == SPNG_CRC_USE)
88|        goto skip_crc;
89|
90|    if(ctx->cur_actual_crc != ctx->current_chunk.crc) return SPNG_ECHUNK_CRC;
91|
92|skip_crc:
93|
94|    return 0;
95|}
