129|/* Read chunk bytes and update crc */
130|static int read_chunk_bytes(spng_ctx *ctx, uint32_t bytes)
131|{
132|    if(ctx == NULL) return 1;
133|    if(!bytes) return 0;
134|    if(bytes > ctx->cur_chunk_bytes_left) return 1; /* XXX: more specific error? */
135|
136|    int ret;
137|
138|    ret = read_data(ctx, bytes);
139|    if(ret) return ret;
140|
141|    if(is_critical_chunk(&ctx->current_chunk) &&
142|       ctx->crc_action_critical == SPNG_CRC_USE) goto skip_crc;
143|    else if(ctx->crc_action_ancillary == SPNG_CRC_USE) goto skip_crc;
144|
145|    ctx->cur_actual_crc = crc32(ctx->cur_actual_crc, ctx->data, bytes);
146|    
147|skip_crc:
148|    ctx->cur_chunk_bytes_left -= bytes;
149|
150|    return ret;
151|}
