316|/*
317|    Read and validate all critical and relevant ancillary chunks up to the first IDAT
318|    Returns zero and sets ctx->first_idat on success
319|*/
320|static int get_ancillary_data_first_idat(spng_ctx *ctx)
321|{
322|    if(ctx == NULL) return 1;
323|    if(ctx->data == NULL) return 1;
324|    if(!ctx->valid_state) return SPNG_EBADSTATE;
325|
326|    int ret;
327|    unsigned char *data;
328|    struct spng_chunk chunk;
329|
330|    chunk.offset = 8;
331|    chunk.length = 13;
332|    size_t sizeof_sig_ihdr = 29;
333|
334|    ret = read_data(ctx, sizeof_sig_ihdr);
335|    if(ret) return ret;
336|
337|    data = ctx->data;
338|
339|    uint8_t signature[8] = { 137, 80, 78, 71, 13, 10, 26, 10 };
340|    if(memcmp(data, signature, sizeof(signature))) return SPNG_ESIGNATURE;
341|
342|    chunk.length = read_u32(data + 8);
343|    memcpy(&chunk.type, data + 12, 4);
344|
345|    if(chunk.length != 13) return SPNG_EIHDR_SIZE;
346|    if(memcmp(chunk.type, type_ihdr, 4)) return SPNG_ENOIHDR;
347|
348|    ctx->cur_actual_crc = crc32(0, NULL, 0);
349|    ctx->cur_actual_crc = crc32(ctx->cur_actual_crc, data + 12, 17);
350|
351|    ctx->ihdr.width = read_u32(data + 16);
352|    ctx->ihdr.height = read_u32(data + 20);
353|    memcpy(&ctx->ihdr.bit_depth, data + 24, 1);
354|    memcpy(&ctx->ihdr.color_type, data + 25, 1);
355|    memcpy(&ctx->ihdr.compression_method, data + 26, 1);
356|    memcpy(&ctx->ihdr.filter_method, data + 27, 1);
357|    memcpy(&ctx->ihdr.interlace_method, data + 28, 1);
358|
359|    if(!ctx->max_width) ctx->max_width = png_u32max;
360|    if(!ctx->max_height) ctx->max_height = png_u32max;
361|
362|    ret = check_ihdr(&ctx->ihdr, ctx->max_width, ctx->max_height);
363|    if(ret) return ret;
364|
365|    ctx->file_ihdr = 1;
366|    ctx->stored_ihdr = 1;
367|
368|    while( !(ret = read_header(ctx)))
369|    {
370|        memcpy(&chunk, &ctx->current_chunk, sizeof(struct spng_chunk));
371|
372|        if(!memcmp(chunk.type, type_idat, 4))
373|        {
374|            memcpy(&ctx->first_idat, &chunk, sizeof(struct spng_chunk));
375|            return 0;
376|        }
377|
378|        ret = read_chunk_bytes(ctx, chunk.length);
379|        if(ret) return ret;
380|
381|        data = ctx->data;
382|
383|        /* Reserved bit must be zero */
384|        if( (chunk.type[2] & (1 << 5)) != 0) return SPNG_ECHUNK_TYPE;
