426|            ctx->chrm_int.white_point_x = read_u32(data);
427|            ctx->chrm_int.white_point_y = read_u32(data + 4);
428|            ctx->chrm_int.red_x = read_u32(data + 8);
429|            ctx->chrm_int.red_y = read_u32(data + 12);
430|            ctx->chrm_int.green_x = read_u32(data + 16);
431|            ctx->chrm_int.green_y = read_u32(data + 20);
432|            ctx->chrm_int.blue_x = read_u32(data + 24);
433|            ctx->chrm_int.blue_y = read_u32(data + 28);
434|
435|            if(check_chrm_int(&ctx->chrm_int)) return SPNG_ECHRM;
436|
437|            ctx->file_chrm = 1;
438|            ctx->stored_chrm = 1;
