464|            if(ctx->file_plte && chunk.offset > ctx->plte_offset) return SPNG_ECHUNK_POS;
465|            if(ctx->file_sbit) return SPNG_EDUP_SBIT;
466|
467|            if(ctx->ihdr.color_type == 0)
468|            {
469|                if(chunk.length != 1) return SPNG_ECHUNK_SIZE;
470|
471|                memcpy(&ctx->sbit.grayscale_bits, data, 1);
472|            }
473|            else if(ctx->ihdr.color_type == 2 || ctx->ihdr.color_type == 3)
474|            {
475|                if(chunk.length != 3) return SPNG_ECHUNK_SIZE;
476|
477|                memcpy(&ctx->sbit.red_bits, data, 1);
478|                memcpy(&ctx->sbit.green_bits, data + 1 , 1);
479|                memcpy(&ctx->sbit.blue_bits, data + 2, 1);
480|            }
481|            else if(ctx->ihdr.color_type == 4)
482|            {
483|                if(chunk.length != 2) return SPNG_ECHUNK_SIZE;
484|
485|                memcpy(&ctx->sbit.grayscale_bits, data, 1);
486|                memcpy(&ctx->sbit.alpha_bits, data + 1, 1);
487|            }
488|            else if(ctx->ihdr.color_type == 6)
489|            {
490|                if(chunk.length != 4) return SPNG_ECHUNK_SIZE;
491|
492|                memcpy(&ctx->sbit.red_bits, data, 1);
493|                memcpy(&ctx->sbit.green_bits, data + 1, 1);
494|                memcpy(&ctx->sbit.blue_bits, data + 2, 1);
495|                memcpy(&ctx->sbit.alpha_bits, data + 3, 1);
496|            }
497|
498|            if(check_sbit(&ctx->sbit, &ctx->ihdr)) return SPNG_ESBIT;
499|
500|            ctx->file_sbit = 1;
501|            ctx->stored_sbit = 1;
502|        }
503|        else if(!memcmp(chunk.type, type_srgb, 4))
504|        {
505|            if(ctx->file_plte && chunk.offset > ctx->plte_offset) return SPNG_ECHUNK_POS;
506|            if(ctx->file_srgb) return SPNG_EDUP_SRGB;
507|
508|            if(chunk.length != 1) return SPNG_ECHUNK_SIZE;
509|
510|            memcpy(&ctx->srgb_rendering_intent, data, 1);
511|
512|            if(ctx->srgb_rendering_intent > 3) return SPNG_ESRGB;
513|
514|            ctx->file_srgb = 1;
515|            ctx->stored_srgb = 1;
516|        }
517|        else if(!memcmp(chunk.type, type_bkgd, 4))
518|        {
519|            if(ctx->file_plte && chunk.offset < ctx->plte_offset) return SPNG_ECHUNK_POS;
520|            if(ctx->file_bkgd) return SPNG_EDUP_BKGD;
521|
522|            uint16_t mask = ~0;
523|            if(ctx->ihdr.bit_depth < 16) mask = (1 << ctx->ihdr.bit_depth) - 1;
524|
525|            if(ctx->ihdr.color_type == 0 || ctx->ihdr.color_type == 4)
526|            {
527|                if(chunk.length != 2) return SPNG_ECHUNK_SIZE;
528|
529|                ctx->bkgd.gray = read_u16(data) & mask;
530|            }
