52|unsigned char *getimage_libpng(unsigned char *buf, size_t size, size_t *out_size, int fmt, int flags)
53|{
54|    png_infop info_ptr;
55|    png_structp png_ptr;
56|    struct buf_state state;
57|
58|    state.data = buf;
59|    state.bytes_left = size;
60|
61|    unsigned char *image = NULL;
62|    png_bytep *row_pointers = NULL;
63|
64|    png_ptr = png_create_read_struct(PNG_LIBPNG_VER_STRING, NULL, NULL, NULL);
65|    if(png_ptr == NULL)
66|    {
67|        printf("libpng init failed\n");
68|        return NULL;
69|    }
70|#if defined(TEST_SPNG_ANALYZE_MALLOC)
71|    png_set_mem_fn(png_ptr, NULL, malloc_fn, free_fn);
72|#endif
73|
74|    info_ptr = png_create_info_struct(png_ptr);
75|    if(info_ptr == NULL)
76|    {
77|        printf("png_create_info_struct failed\n");
78|        return NULL;
79|    }
80|
81|    if(setjmp(png_jmpbuf(png_ptr)))
82|    {
83|        printf("libpng error\n");
84|        png_destroy_read_struct(&png_ptr, &info_ptr, NULL);
85|        if(image != NULL) free(image);
86|        if(row_pointers != NULL) free(row_pointers);
87|        return NULL;
88|    }
89|
90|    png_set_read_fn(png_ptr, &state, libpng_read_fn);
91|
92|    if(png_sig_cmp(buf, 0, 8))
93|    {
94|        printf("libpng: invalid signature\n");
95|        return NULL;
96|    }
97|
98|    png_read_info(png_ptr, info_ptr);
99|
100|    png_uint_32 width, height;
101|    int bit_depth, colour_type, interlace_type, compression_type;
102|    int filter_method;
103|
104|    if(!png_get_IHDR(png_ptr, info_ptr, &width, &height, &bit_depth,
105|                     &colour_type, &interlace_type, &compression_type, &filter_method))
106|    {
107|        printf("png_get_IHDR failed\n");
108|        return NULL;
109|    }
110|
111|    if(flags & SPNG_DECODE_USE_GAMA)
112|    {
113|        double gamma;
114|        if(png_get_gAMA(png_ptr, info_ptr, &gamma))
115|            png_set_gamma(png_ptr, 2.2, gamma);
116|    }
117|
118|    if(fmt == SPNG_FMT_RGBA16)
119|    {
120|        png_set_gray_to_rgb(png_ptr);
121|
122|        png_set_filler(png_ptr, 0xFFFF, PNG_FILLER_AFTER);
123|
124|        /* png_set_palette_to_rgb() + png_set_tRNS_to_alpha() */
125|        png_set_expand_16(png_ptr);
126|
127|        png_set_swap(png_ptr);
128|    }
129|    else if(fmt == SPNG_FMT_RGBA8)
130|    {
131|        png_set_gray_to_rgb(png_ptr);
132|
133|        png_set_filler(png_ptr, 0xFF, PNG_FILLER_AFTER);
134|
135|        /* png_set_palette_to_rgb() + png_set_expand_gray_1_2_4_to_8() + png_set_tRNS_to_alpha() */
136|        png_set_expand(png_ptr);
137|
138|        png_set_strip_16(png_ptr);
139|    }
140|
141|    png_set_interlace_handling(png_ptr);
142|    png_read_update_info(png_ptr, info_ptr);
143|
144|    size_t rowbytes = png_get_rowbytes(png_ptr, info_ptr);
145|
146|    /* avoid calling malloc() for each row */
147|    size_t image_size = height * rowbytes;
148|    memcpy(out_size, &image_size, sizeof(size_t));
149|
150|    image = malloc(image_size);
151|    if(image == NULL)
152|    {
153|         printf("libpng: malloc() failed\n");
154|         png_destroy_read_struct(&png_ptr, &info_ptr, NULL);
155|         return NULL;
156|    }
157|
158|    row_pointers = malloc(height * sizeof(png_bytep));
159|    if(row_pointers == NULL)
160|    {
161|        printf("libpng: malloc() failed\n");
162|        free(image);
163|        png_destroy_read_struct(&png_ptr, &info_ptr, NULL);
164|        return NULL;
165|    }
166|
167|    int k;
168|    for(k=0; k < height; k++)
169|    {
170|        row_pointers[k] = image + k * rowbytes;
171|    }
172|
173|    png_read_image(png_ptr, row_pointers);
174|
175|    png_read_end(png_ptr, info_ptr);
176|
177|    free(row_pointers);
178|
179|    png_destroy_read_struct(&png_ptr, &info_ptr, NULL);
180|
181|    return image;
182|}

