35|void gen_test_cases(struct spng_test_case *test_cases, int *test_cases_n)
36|{
37|    const int fmt_list[] = { SPNG_FMT_RGBA8, SPNG_FMT_RGBA16 };
38|    const int fmt_n = 2;
39|
40|    int i, j;
41|    int k = 0;
42|
43|    for(i=0; i < fmt_n; i++)
44|    {
45|    /* With libpng it's not possible to request 8/16-bit images regardless of
46|       PNG format without calling functions that alias to png_set_expand(_16),
47|       which acts as if png_set_tRNS_to_alpha() was called, as a result
48|       there are no tests where the tRNS chunk is ignored. */
49|        for(j=1; j <= SPNG_DECODE_USE_GAMA; j++, k++)
