59|int compare_images(struct spng_ihdr *ihdr, int fmt, int flags, unsigned char *img_spng, unsigned char *img_png)
60|{
61|    uint32_t w, h;
62|    uint32_t x, y;
63|    uint8_t have_alpha = 1;
64|    uint8_t alpha_mismatch = 0;
65|    uint8_t pixel_diff = 0;
66|    uint8_t bytes_per_pixel = 4; /* SPNG_FMT_RGBA8 */
67|
68|    uint16_t spng_red = 0, spng_green = 0, spng_blue = 0, spng_alpha = 0;
69|    uint16_t png_red = 0, png_green = 0, png_blue = 0, png_alpha = 0;
70|
71|    w = ihdr->width;
72|    h = ihdr->height;
73|
74|    if(fmt == SPNG_FMT_RGBA8)
75|    {
76|        bytes_per_pixel = 4;
77|    }
78|    else if(fmt == SPNG_FMT_RGBA16)
79|    {
80|        bytes_per_pixel = 8;
81|    }
82|
83|    for(y=0; y < h; y++)
84|    {
85|        for(x=0; x < w; x++)
86|        {
87|            if(fmt == SPNG_FMT_RGBA16)
88|            {
89|                uint16_t s_red, s_green, s_blue, s_alpha;
90|                uint16_t p_red, p_green, p_blue, p_alpha;
91|
92|                size_t px_ofs = (x + (y * w)) * bytes_per_pixel;
93|
94|                    memcpy(&s_red, img_spng + px_ofs, 2);
95|                    memcpy(&s_green, img_spng + px_ofs + 2, 2);
96|                    memcpy(&s_blue, img_spng + px_ofs + 4, 2);
97|
98|                    memcpy(&p_red, img_png + px_ofs, 2);
99|                    memcpy(&p_green, img_png + px_ofs + 2, 2);
100|                    memcpy(&p_blue, img_png + px_ofs + 4, 2);
101|
102|                    if(have_alpha)
103|                    {
104|                        memcpy(&s_alpha, img_spng + px_ofs + 6, 2);
105|                        memcpy(&p_alpha, img_png + px_ofs + 6, 2);
106|                        spng_alpha = s_alpha;
107|                        png_alpha = p_alpha;
108|                    }
109|
110|                    spng_red = s_red;
111|                    spng_green = s_green;
112|                    spng_blue = s_blue;
113|
114|                    png_red = p_red;
115|                    png_green = p_green;
116|                    png_blue = p_blue;
117|            }
118|            else /* FMT_RGBA8 */
119|            {
120|                uint8_t s_red, s_green, s_blue, s_alpha;
121|                uint8_t p_red, p_green, p_blue, p_alpha;
122|
123|                size_t px_ofs = (x + (y * w)) * bytes_per_pixel;
124|
125|                memcpy(&s_red, img_spng + px_ofs, 1);
126|                memcpy(&s_green, img_spng + px_ofs + 1, 1);
127|                memcpy(&s_blue, img_spng + px_ofs + 2, 1);
128|
129|                memcpy(&p_red, img_png + px_ofs, 1);
130|                memcpy(&p_green, img_png + px_ofs + 1, 1);
131|                memcpy(&p_blue, img_png + px_ofs + 2, 1);
132|
133|                if(have_alpha)
134|                {
135|                    memcpy(&s_alpha, img_spng + px_ofs + 3, 1);
136|                    memcpy(&p_alpha, img_png + px_ofs + 3, 1);
137|                    spng_alpha = s_alpha;
138|                    png_alpha = p_alpha;
139|                }
140|
141|                spng_red = s_red;
142|                spng_green = s_green;
143|                spng_blue = s_blue;
144|
145|                png_red = p_red;
146|                png_green = p_green;
147|                png_blue = p_blue;
148|
149|            }
150|
151|            if(have_alpha && spng_alpha != png_alpha)
152|            {
153|                printf("alpha mismatch at x:%" PRIu32 " y:%" PRIu32 ", "
154|                       "spng: %" PRIu16 " png: %" PRIu16 "\n",
155|                       x, y,
156|                       spng_alpha, png_alpha);
157|                alpha_mismatch = 1;
158|            }
159|
160|            if(spng_red != png_red || spng_green != png_green || spng_blue != png_blue)
161|            {
162|                if(flags & SPNG_DECODE_USE_GAMA)
163|                {
164|                    uint32_t red_diff, green_diff, blue_diff;
165|                    uint32_t max_diff=0;
166|
167|                    /* allow up to ~2% difference for each channel */
168|                    if(fmt == SPNG_FMT_RGBA8) max_diff = 256 / 50;
169|                    else if(fmt == SPNG_FMT_RGBA16) max_diff = 65536 / 50;
170|
171|                    red_diff = abs(spng_red - png_red);
172|                    green_diff = abs(spng_green - png_green);
173|                    blue_diff = abs(spng_blue - png_blue);
174|
175|                    if(red_diff > max_diff || green_diff > max_diff || blue_diff > max_diff)
176|                    {
177|                        printf("invalid gamma correction at x: %" PRIu32 " y:%" PRIu32 ", "
178|                               "spng: %" PRIu16 " %" PRIu16 " %" PRIu16 " "
179|                               "png: %" PRIu16 " %" PRIu16 " %" PRIu16 "\n",
180|                               x, y,
181|                               spng_red, spng_green, spng_blue,
182|                               png_red, png_green, png_blue);
183|                        pixel_diff = 1;
184|                    }
185|                }
186|                else
187|                {
188|                    printf("color difference at x: %" PRIu32 " y:%" PRIu32 ", "
189|                           "spng: %" PRIu16 " %" PRIu16 " %" PRIu16 " "
190|                           "png: %" PRIu16 " %" PRIu16 " %" PRIu16 "\n",
191|                           x, y,
192|                           spng_red, spng_green, spng_blue,
193|                           png_red, png_green, png_blue);
194|                    pixel_diff = 1;
195|                }
196|            }
197|        }
198|    }
199|
200|    if(alpha_mismatch || pixel_diff) return 1;
201|
202|    return 0;
203|}

205|int decode_and_compare(unsigned char *pngbuf, size_t siz_pngbuf, int fmt, int flags)
206|{
207|    struct spng_ihdr ihdr;
208|    size_t img_spng_size;
209|    unsigned char *img_spng =  NULL;
210|
211|    img_spng = getimage_libspng(pngbuf, siz_pngbuf, &img_spng_size, fmt, flags, &ihdr);
212|    if(img_spng==NULL)
213|    {
214|        printf("getimage_libspng() failed\n");
215|        return 1;
216|    }
217|
218|    /* return 0 for should_fail tests if spng can't detect an invalid file */
219|    if(should_fail)
220|    {
221|        free(img_spng);
222|        return 0;
223|    }
224|
225|    size_t img_png_size;
226|    unsigned char *img_png = NULL;
227|
228|    img_png = getimage_libpng(pngbuf, siz_pngbuf, &img_png_size, fmt, flags);
229|    if(img_png==NULL)
230|    {
231|        printf("getimage_libpng() failed\n");
232|        free(img_spng);
233|        return 1;
234|    }
235|
236|    if(img_png_size != img_spng_size)
237|    {
238|        printf("output image size mismatch\n");
239|        printf("spng: %zu\n png: %zu\n", img_spng_size, img_png_size);
240|        free(img_spng);
241|        free(img_png);
242|        return 1;
243|    }
244|
245|    int ret = 0;
246|    int ret_memcmp = memcmp(img_spng, img_png, img_spng_size);
247|
248|    if(!ret_memcmp) goto identical;
249|
250|    ret = compare_images(&ihdr, fmt, flags, img_spng, img_png);
251|
252|    if( !(flags & SPNG_DECODE_USE_GAMA) && !ret)
253|    {/* in case compare_images() has some edge case */
254|        printf("compare_images() returned 0 but images are not identical\n");
255|        ret = 1;
256|    }
257|
258|identical:
259|
260|    free(img_spng);
261|    free(img_png);
262|
263|    return ret;
264|}

