107|void png_read_filter_row_avg3(size_t rowbytes, png_bytep row,
108|   png_const_bytep prev)
109|{
110|   /* The Avg filter predicts each pixel as the (truncated) average of a and b.
111|    * There's no pixel to the left of the first pixel.  Luckily, it's
112|    * predicted to be half of the pixel above it.  So again, this works
113|    * perfectly with our loop if we make sure a starts at zero.
114|    */
115|
116|   size_t rb = rowbytes;
117|
118|   const __m128i zero = _mm_setzero_si128();
119|
120|   __m128i    b;
121|   __m128i a, d = zero;
122|
123|   while (rb >= 4) {
124|      __m128i avg;
125|             b = load4(prev);
126|      a = d; d = load4(row );
127|
128|      /* PNG requires a truncating average, so we can't just use _mm_avg_epu8 */
129|      avg = _mm_avg_epu8(a,b);
130|      /* ...but we can fix it up by subtracting off 1 if it rounded up. */
131|      avg = _mm_sub_epi8(avg, _mm_and_si128(_mm_xor_si128(a,b),
132|                                            _mm_set1_epi8(1)));
133|      d = _mm_add_epi8(d, avg);
134|      store3(row, d);
135|
136|      prev += 3;
137|      row  += 3;
138|      rb   -= 3;
139|   }
140|   if (rb > 0) {
141|      __m128i avg;
142|             b = load3(prev);
143|      a = d; d = load3(row );
144|
145|      /* PNG requires a truncating average, so we can't just use _mm_avg_epu8 */
146|      avg = _mm_avg_epu8(a,b);
147|      /* ...but we can fix it up by subtracting off 1 if it rounded up. */
148|      avg = _mm_sub_epi8(avg, _mm_and_si128(_mm_xor_si128(a,b),
149|                                            _mm_set1_epi8(1)));
150|
