156|void png_read_filter_row_avg4(size_t rowbytes, png_bytep row,
157|   png_const_bytep prev)
158|{
159|   /* The Avg filter predicts each pixel as the (truncated) average of a and b.
160|    * There's no pixel to the left of the first pixel.  Luckily, it's
161|    * predicted to be half of the pixel above it.  So again, this works
162|    * perfectly with our loop if we make sure a starts at zero.
163|    */
164|   size_t rb = rowbytes+4;
165|
166|   const __m128i zero = _mm_setzero_si128();
167|   __m128i    b;
168|   __m128i a, d = zero;
169|
170|   while (rb > 4) {
171|      __m128i avg;
172|             b = load4(prev);
173|      a = d; d = load4(row );
174|
175|      /* PNG requires a truncating average, so we can't just use _mm_avg_epu8 */
176|      avg = _mm_avg_epu8(a,b);
177|      /* ...but we can fix it up by subtracting off 1 if it rounded up. */
178|      avg = _mm_sub_epi8(avg, _mm_and_si128(_mm_xor_si128(a,b),
179|                                            _mm_set1_epi8(1)));
180|
181|      d = _mm_add_epi8(d, avg);
182|      store4(row, d);
183|
184|      prev += 4;
185|      row  += 4;
186|      rb   -= 4;
187|   }
188|}

